<template>
    <view class="fw-page op-page"><view class="fw-header"><text class="fw-subtitle">按完整批号关联工序、人员、报工、交接和异常。</text></view><view class="fw-search"><input v-model="batchNo" maxlength="20" placeholder="完整批号" @input="result = null" confirm-type="search" @confirm="load" /><text class="fw-link" @tap="load">查询</text></view><view v-if="error" class="fw-notice error">{{ error }}</view><view v-if="result" class="fw-notice">当前显示 {{ queriedBatch }} 的生产执行记录，原始指令单及订单版本可在后台“批号追溯”查看。</view><view v-if="result" class="fw-card"><text class="fw-heading-title">工单与人员</text><view v-for="job in result.jobs" :key="job._id" class="op-row" @tap="openJob(job)"><view><text class="op-name">{{ job.processName }} · {{ states[job.state] }}</text><text class="op-meta">{{ job.productCode }} · {{ job.productName }}</text><text class="op-meta">{{ (job.personNames || []).join('、') }} · 订单 {{ job.orderNo }} V{{ job.orderVersion }}</text></view></view><text v-if="!result.jobs.length" class="op-meta">当前范围没有此批工单。</text></view><view v-if="result" class="fw-card"><text class="fw-heading-title">交接记录</text><view v-for="row in result.handovers" :key="row._id" class="op-row" @tap="openHandover(row)"><view><text class="op-name">{{ row.date }} · {{ handoverStates[row.status] }}</text><text class="op-meta">{{ row.authorName }} → {{ row.receiverName }}</text><text class="op-meta">{{ row.content }}</text></view></view><text v-if="!result.handovers.length" class="op-meta">没有关联交接记录。</text></view><view v-if="result" class="fw-card"><text class="fw-heading-title">异常及处理</text><view v-for="row in result.exceptions" :key="row._id" class="op-row"><view><text class="op-name">{{ row.status === 'resolved' ? '已处理' : '待处理' }}</text><text class="op-pre">{{ row.description }}</text><text v-if="row.resolution" class="op-meta">{{ row.resolution }}</text></view></view><text v-if="!result.exceptions.length" class="op-meta">没有关联异常。</text></view></view>
</template>
<script>
import { callOperations, operationsPage, loadOperations, JOB_STATES, HANDOVER_STATES } from '@/utils/operations-api.js'
export default { mixins: [operationsPage], data() { return { batchNo: '', queriedBatch: '', result: null, states: JOB_STATES, handoverStates: HANDOVER_STATES } }, onLoad(options) { this.batchNo = options.batchNo || ''; if (this.batchNo) this.load() }, methods: {
    load() { const batchNo = this.batchNo.trim().toUpperCase(); if (!/^(?=.*[A-Z])(?=.*\d)[A-Z0-9]{11,20}$/.test(batchNo)) { this.error = '请输入完整批号，不要使用前缀'; this.result = null; return }; return loadOperations(this, () => callOperations('trace', { batchNo }), result => { this.result = result; this.queriedBatch = batchNo }) }, clearLoaded() { this.result = null }, openJob(job) { uni.navigateTo({ url: '/pages/operations/job-detail?id=' + encodeURIComponent(job._id) }) }, openHandover(row) { uni.navigateTo({ url: '/pages/operations/handover-detail?id=' + encodeURIComponent(row._id) }) }
} }
</script>
<style lang="scss" scoped>@import '@/styles/operations.scss';</style>
